import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const RequestLeavePage = () => {
  const navigate = useNavigate();

  // State to hold the form data. Field names match the backend serializer.
  const [formData, setFormData] = useState({
    employee_id: '', // Crucially, this must match the 'write_only' field in the serializer
    leave_type: 'Casual Leave',
    start_date: '',
    end_date: '',
    reason: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({ ...prevState, [name]: value }));
  };

  // The handleSubmit function with the updated catch block
  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log("Submitting new leave request to backend:", formData);

    try {
      // Send a POST request to the backend API with the form data
      await axios.post('http://127.0.0.1:8000/api/leave-requests/', formData);

      alert('Your leave request has been submitted successfully!');
      navigate('/leave-tracker'); // Redirect back to the list on success
    } catch (error) {
      // --- THIS IS THE UPDATED, MORE ROBUST CATCH BLOCK ---
      console.error('Error submitting leave request:', error);
      if (error.response && error.response.data) {
        // Check if the error data from Django is a simple string
        if (typeof error.response.data === 'string') {
          alert(`Failed to submit request: ${error.response.data}`);
        } 
        // Check if it's the structured validation error object
        else {
          const errorMessages = Object.entries(error.response.data)
            .map(([field, messages]) => {
              // Check if the 'messages' part is an array before trying to join it
              if (Array.isArray(messages)) {
                return `${field}: ${messages.join(', ')}`;
              }
              // If it's not an array (e.g., a simple string), just display it
              return `${field}: ${String(messages)}`;
            })
            .join('\n');
          alert(`Failed to submit request:\n\n${errorMessages}`);
        }
      } else {
        // This handles network errors where there's no response from the server at all
        alert('Failed to submit request. Could not connect to the backend.');
      }
    }
  };

  return (
    <div className="flex flex-col h-full">
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light"><h1 className="text-2xl font-semibold">Submit a New Leave Request</h1></header>
      <main className="flex-1 p-8">
        <div className="max-w-2xl mx-auto bg-card-light p-8 rounded-lg shadow-md">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label htmlFor="employee_id" className="block text-sm font-medium text-subtext-light">Employee ID</label>
              <input type="number" name="employee_id" id="employee_id" value={formData.employee_id} onChange={handleChange} required className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md" placeholder="Enter a valid, existing employee ID (e.g., 1)" />
            </div>

            <div>
              <label htmlFor="leave_type" className="block text-sm font-medium text-subtext-light">Leave Type</label>
              <select name="leave_type" id="leave_type" value={formData.leave_type} onChange={handleChange} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md appearance-none pr-8">
                <option>Casual Leave</option>
                <option>Sick Leave</option>
                <option>Earned Leave</option>
              </select>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="start_date" className="block text-sm font-medium text-subtext-light">Start Date</label>
                <input type="date" name="start_date" id="start_date" value={formData.start_date} onChange={handleChange} required className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md" />
              </div>
              <div>
                <label htmlFor="end_date" className="block text-sm font-medium text-subtext-light">End Date</label>
                <input type="date" name="end_date" id="end_date" value={formData.end_date} onChange={handleChange} required className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md" />
              </div>
            </div>

            <div>
              <label htmlFor="reason" className="block text-sm font-medium text-subtext-light">Reason for Leave</label>
              <textarea name="reason" id="reason" rows="4" value={formData.reason} onChange={handleChange} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md" placeholder="Briefly explain the reason for your leave..."></textarea>
            </div>

            <div className="flex justify-end gap-4 border-t border-border-light pt-6">
              <button type="button" onClick={() => navigate('/leave-tracker')} className="bg-gray-200 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-300">Cancel</button>
              <button type="submit" className="bg-primary text-white px-6 py-2 rounded-lg hover:bg-blue-600">Submit Request</button>
            </div>
          </form>
        </div>
      </main>
    </div>
  );
};

export default RequestLeavePage;
